def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    my_def = sum(1 for a, b in history if a == 'D')
    opp_def = sum(1 for a, b in history if b == 'D')
    opp_c = n - opp_def
    my_c = n - my_def

    retal = 0
    for i in range(n - 1):
        if history[i][0] == 'D' and history[i + 1][1] == 'D':
            retal += 1

    if n == 98:
        if retal > 0:
            return 'C'
        else:
            return 'D'

    if n == 97:
        if retal == 0 and my_def > 0:
            return 'D'

    if n == 20 and my_def == 0 and opp_def == 0:
        return 'D'

    if my_def > 0 and retal == 0:
        if n % 7 == 0 and n < 95:
            return 'D'

    last_opp = history[-1][1]
    if n < 8:
        return 'C' if last_opp == 'C' else 'D'

    if opp_c >= 95:
        return 'C'
    if opp_c <= 3 and n >= 20:
        return 'D'

    recent = history[-12:]
    opp_recent_c = sum(1 for a, b in recent if b == 'C')
    if opp_recent_c == 0:
        if rng.random() < 0.08:
            return 'C'
        return 'D'
    if opp_recent_c >= 11:
        return 'C'

    perceived_forgiveness = opp_c / n
    if perceived_forgiveness > 0.65:
        if last_opp == 'D' and history[-2][1] == 'C' and rng.random() < 0.7:
            return 'D'
        return 'C'
    if my_c / n > 0.75 and last_opp == 'D':
        return 'D'
    if n > 60 and opp_c > 35 and my_c < 30:
        return 'C'
    if last_opp == 'D':
        if rng.random() < 0.15 + 0.25 * (opp_recent_c / 12):
            return 'C'
        return 'D'
    if n % 10 == 9 and my_c > opp_c + 10:
        return 'D'
    return 'C'
